2150  internal_exr_compute_tile_information (
  2151      struct _internal_exr_context* ctxt,
  2152      struct _internal_exr_part*    curpart,
  2153      int                           rebuild)
  2154  {
  2155      exr_result_t rv = EXR_ERR_SUCCESS;
  2156      if (curpart->storage_mode == EXR_STORAGE_SCANLINE ||
  2157          curpart->storage_mode == EXR_STORAGE_DEEP_SCANLINE)
  2158          return EXR_ERR_SUCCESS;
  2159
  2160      if (rebuild && (!curpart->dataWindow || !curpart->tiles))
  2161          return EXR_ERR_SUCCESS;
  2162
  2163      if (!curpart->tiles)
  2164          return ctxt->standard_error (ctxt, EXR_ERR_MISSING_REQ_ATTR);
  2165
  2166      if (rebuild)
  2167      {
  2168          if (curpart->tile_level_tile_count_x)
  2169          {
  2170              ctxt->free_fn (curpart->tile_level_tile_count_x);
  2171              curpart->tile_level_tile_count_x = NULL;
  2172          }
  2173      }
  2174
  2175      if (curpart->tile_level_tile_count_x == NULL)
  2176      {
  2177          const exr_attr_box2i_t     dw       = curpart->data_window;
  2178          const exr_attr_tiledesc_t* tiledesc = curpart->tiles->tiledesc;
  2179          int64_t                    w, h;
  2180          int32_t                    numX, numY;
  2181          int32_t*                   levcntX = NULL;
  2182          int32_t*                   levcntY = NULL;
  2183          int32_t*                   levszX  = NULL;
  2184          int32_t*                   levszY  = NULL;
  2185
  2186          w = ((int64_t) dw.max.x) - ((int64_t) dw.min.x) + 1;
  2187          h = ((int64_t) dw.max.y) - ((int64_t) dw.min.y) + 1;
  2188
  2189          if (tiledesc->x_size == 0 || tiledesc->y_size == 0)
  2190              return ctxt->standard_error (ctxt, EXR_ERR_INVALID_ATTR);
  2191          switch (EXR_GET_TILE_LEVEL_MODE ((*tiledesc)))
  2192          {
  2193              case EXR_TILE_ONE_LEVEL: numX = numY = 1; break;
  2194              case EXR_TILE_MIPMAP_LEVELS:
  2195                  if (EXR_GET_TILE_ROUND_MODE ((*tiledesc)) ==
  2196                      EXR_TILE_ROUND_DOWN)
  2197                  {
  2198                      numX = floor_log2 (w > h ? w : h) + 1;
  2199                      numY = numX;
  2200                  }
  2201                  else
  2202                  {
  2203                      numX = ceil_log2 (w > h ? w : h) + 1;
  2204                      numY = numX;
  2205                  }
  2206                  break;
  2207              case EXR_TILE_RIPMAP_LEVELS:
  2208                  if (EXR_GET_TILE_ROUND_MODE ((*tiledesc)) ==
  2209                      EXR_TILE_ROUND_DOWN)
  2210                  {
  2211                      numX = floor_log2 (w) + 1;
  2212                      numY = floor_log2 (h) + 1;
  2213                  }
  2214                  else
  2215                  {
  2216                      numX = ceil_log2 (w) + 1;
  2217                      numY = ceil_log2 (h) + 1;
  2218                  }
  2219                  break;
  2220              case EXR_TILE_LAST_TYPE:
  2221              default: return ctxt->standard_error (ctxt, EXR_ERR_INVALID_ATTR);
  2222          }
  2223
  2224          curpart->num_tile_levels_x = numX;
  2225          curpart->num_tile_levels_y = numY;
  2226          levcntX                    = (int32_t*) ctxt->alloc_fn (
  2227              2 * (size_t) (numX + numY) * sizeof (int32_t));
  2228          if (levcntX == NULL)
  2229              return ctxt->standard_error (ctxt, EXR_ERR_OUT_OF_MEMORY);
  2230          levszX  = levcntX + numX;
  2231          levcntY = levszX + numX;
  2232          levszY  = levcntY + numY;
  2233
  2234          for (int32_t l = 0; l < numX; ++l)
  2235          {
  2236              int64_t sx = calc_level_size (
  2237                  dw.min.x, dw.max.x, l, EXR_GET_TILE_ROUND_MODE ((*tiledesc)));
  2238              if (sx < 0 || sx > (int64_t) INT32_MAX)
  2239                  return ctxt->print_error (
  2240                      ctxt,
  2241                      EXR_ERR_INVALID_ATTR,
  2242                      "Invalid data window x dims (%d, %d) resulting in invalid tile level size (%" PRId64
  2243                      ") for level %d",
  2244                      dw.min.x,
  2245                      dw.max.x,
  2246                      sx,
  2247                      l);
  2248              levcntX[l] =
  2249                  (int32_t) (((uint64_t) sx + tiledesc->x_size - 1) / tiledesc->x_size);
  2250              levszX[l] = (int32_t) sx;
  2251          }
  2252
  2253          for (int32_t l = 0; l < numY; ++l)
  2254          {
  2255              int64_t sy = calc_level_size (
  2256                  dw.min.y, dw.max.y, l, EXR_GET_TILE_ROUND_MODE ((*tiledesc)));
  2257              if (sy < 0 || sy > (int64_t) INT32_MAX)
  2258                  return ctxt->print_error (
  2259                      ctxt,
  2260                      EXR_ERR_INVALID_ATTR,
  2261                      "Invalid data window y dims (%d, %d) resulting in invalid tile level size (%" PRId64
  2262                      ") for level %d",
  2263                      dw.min.y,
  2264                      dw.max.y,
  2265                      sy,
  2266                      l);
  2267              levcntY[l] =
  2268                  (int32_t) (((uint64_t) sy + tiledesc->y_size - 1) / tiledesc->y_size);
  2269              levszY[l] = (int32_t) sy;
  2270          }
  2271
  2272          curpart->tile_level_tile_count_x = levcntX;
  2273          curpart->tile_level_tile_count_y = levcntY;
  2274          curpart->tile_level_tile_size_x  = levszX;
  2275          curpart->tile_level_tile_size_y  = levszY;
  2276      }
  2277      return rv;
  2278  }
